def flaky(n_fail):
    state = {"n": 0}

    def f():
        state["n"] += 1
        if state["n"] <= n_fail:
            raise RuntimeError("fail")
        return "ok"

    return f


def counter_fn():
    state = {"n": 0}

    def f():
        state["n"] += 1
        return state["n"]

    return f


